import { Group, Mesh, PlaneGeometry, Color } from 'three/webgpu';
import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new Group();
  group.name = 'home-subhead';

  const inner = new Group();
  group.add(inner);

  // ---- palette ----
  const colors = config?.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const inkColor = new Color(colors.ink);
  const surfaceColor = new Color(colors.surface);
  const paperColor = colors.paper ?? '#e8ecf2';
  const accentColor = colors.accent ?? '#ff2a38';

  // ---- panel dimensions ----
  const panelW = 3.4;
  const panelH = 0.9;

  // ---- engineered gradient backdrop (local card, not full stage) ----
  const backdropGeo = new PlaneGeometry(panelW, panelH);
  const backdropMat = new MeshBasicNodeMaterial({ transparent: false });
  const uvNode = uv();
  const topC = vec3(inkColor.r, inkColor.g, inkColor.b);
  const botC = vec3(surfaceColor.r, surfaceColor.g, surfaceColor.b);
  backdropMat.colorNode = mix(botC, topC, uvNode.y);
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -0.06);
  inner.add(backdrop);

  // ---- isolated image plane ----
  const imgW = panelW * 0.86;
  const imgH = panelH * 0.7;
  const imgGeo = new PlaneGeometry(imgW, imgH);
  const imgMat = new MeshBasicNodeMaterial({ transparent: true });
  imgMat.alphaTest = 0.01;
  const imgMesh = new Mesh(imgGeo, imgMat);
  imgMesh.position.set(0, -0.08, -0.03);
  inner.add(imgMesh);

  let loadedTexture = null;
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      loadedTexture = tex;
      imgMat.map = tex;
      imgMat.needsUpdate = true;
    }).catch(() => {});
  }

  // ---- thin accent strip (<=10% of frame area) ----
  const accentGeo = new PlaneGeometry(panelW * 0.94, panelH * 0.045);
  const accentMat = new MeshBasicNodeMaterial({ color: accentColor });
  const accentStrip = new Mesh(accentGeo, accentMat);
  accentStrip.position.set(0, -panelH / 2 + 0.05, -0.02);
  inner.add(accentStrip);

  // ---- text content (ASCII-sanitized, rendered verbatim in meaning) ----
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const rawText =
    items.find((i) => i.role === 'headline')?.text ??
    items[0]?.text ??
    'Atelier Noir - precise - luxury - technical';

  const sanitized = rawText
    .replace(/[\u2014\u2013]/g, '-')
    .replace(/[\u00B7\u2022]/g, '-')
    .replace(/[\u2018\u2019]/g, "'")
    .replace(/[\u201C\u201D]/g, '"');

  const fontSize = items.find((i) => i.role === 'headline')?.typography?.fontSize ?? 42;

  const textObj = ctx.fontAtlas.createText(sanitized, {
    fontSize,
    color: paperColor,
    align: 'center',
    maxWidthPx: 900,
  });
  textObj.position.set(0, panelH / 2 - 0.2, 0.03);
  inner.add(textObj);

  // ---- entrance motion (weighted-settle, translate <=0.4, no linear easing) ----
  inner.position.y = -0.16;
  inner.scale.setScalar(0.98);

  const tl = gsap.timeline();
  tl.to(inner.position, {
    y: 0,
    duration: 0.7,
    ease: 'power3.out',
  }, 0);
  tl.to(inner.scale, {
    x: 1.04,
    y: 1.04,
    z: 1.04,
    duration: 0.35,
    ease: 'power2.out',
  }, 0.15);
  tl.to(inner.scale, {
    x: 1,
    y: 1,
    z: 1,
    duration: 0.55,
    ease: 'power4.out',
  }, 0.5);

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    tl.kill();

    backdropGeo.dispose();
    backdropMat.dispose();

    imgGeo.dispose();
    imgMat.dispose();
    if (loadedTexture && typeof loadedTexture.dispose === 'function') {
      loadedTexture.dispose();
    }

    accentGeo.dispose();
    accentMat.dispose();

    textObj.traverse((child) => {
      if (child.geometry) child.geometry.dispose();
      if (child.material) {
        const mats = Array.isArray(child.material) ? child.material : [child.material];
        mats.forEach((m) => m && m.dispose && m.dispose());
      }
    });
  };

  return group;
}
